import{_ as s,o as a,c as t,a0 as r}from"./chunks/framework.CR-yHhk1.js";const v=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),o={name:"explanation/architecture.md"};function i(n,e,d,c,p,l){return a(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Sepia is the <em>mechanism</em> layer for coding-agent sessions. Everything you can do <strong>to</strong> a session or an agent — list stores, attach, prompt, cancel, resolve permissions, restore, rewind, manage agent configs — is sepia&#39;s job. It has no opinion about <em>who</em> should do those things, <em>when</em>, or <em>from where</em>: that policy lives in <a href="https://9aia.com/peregrin/" target="_blank" rel="noreferrer">peregrin</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>orchestrator (peregrin, scripts, CI)</span></span>
<span class="line"><span>        │  spawn + ndjson JSON-RPC</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   sepia serve ────────── ControlPlane (sepia-session)</span></span>
<span class="line"><span>        │                       │ attach / prompt / restore</span></span>
<span class="line"><span>        │  spawn + ndjson       ▼</span></span>
<span class="line"><span>        └────────────►  sepia-driver-* binaries</span></span>
<span class="line"><span>                                │ per-agent adapters</span></span>
<span class="line"><span>                                ▼</span></span>
<span class="line"><span>                     devin / cline / claude / cursor stores</span></span></code></pre></div><h2 id="why-mechanism-vs-policy" tabindex="-1">Why mechanism vs policy <a class="header-anchor" href="#why-mechanism-vs-policy" aria-label="Permalink to &quot;Why mechanism vs policy&quot;">​</a></h2><p>Two failure modes drove the split. Policy code (arbitration, routing, queues) wants to evolve fast and is mostly pure logic. Session mechanism wants to be boring — a stable IR, tolerant parsers, careful handling of agent stores you did not design. Gluing them together made both worse; the <code>sepia serve</code> boundary keeps them apart: peregrin links none of sepia&#39;s internals, it spawns the service and speaks the same JSON-RPC framing drivers do.</p><h2 id="the-canonical-ir" tabindex="-1">The canonical IR <a class="header-anchor" href="#the-canonical-ir" aria-label="Permalink to &quot;The canonical IR&quot;">​</a></h2><p>Every agent store — Devin&#39;s SQLite, Cline&#39;s directory layout, Claude&#39;s JSONL transcripts, Cursor&#39;s workspace storage — maps onto one session IR: nodes, messages, tool calls, checkpoints, metadata. Lossy edges are marked <code>lossy</code> in metadata rather than silently dropped, so importers and auditors can see what a store could not express. <a href="./../reference/session-formats.html">Session formats</a> documents the shape.</p><h2 id="drivers-are-binaries-not-libraries" tabindex="-1">Drivers are binaries, not libraries <a class="header-anchor" href="#drivers-are-binaries-not-libraries" aria-label="Permalink to &quot;Drivers are binaries, not libraries&quot;">​</a></h2><p>Store adapters ship as <code>sepia-driver-&lt;id&gt;</code> executables speaking ndjson JSON-RPC over stdio. Discovery order: <code>$SEPIA_DRIVER_DIR</code>, the platform data dir (<code>$XDG_DATA_HOME/sepia/drivers</code> or <code>~/.local/share/sepia/drivers</code>), <code>/usr/local/lib/sepia/drivers</code>, then PATH. The session plane never links a driver — a crashed or hung adapter kills a subprocess, not your daemon. Adding an agent is dropping a binary in a discovery dir; see <a href="./../how-to/write-a-driver.html">write a driver</a>.</p><h2 id="crates" tabindex="-1">Crates <a class="header-anchor" href="#crates" aria-label="Permalink to &quot;Crates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Crate</th><th>Role</th></tr></thead><tbody><tr><td><code>sepia-core</code></td><td>Session IR, <code>SessionRepository</code> port, agent-config IR, restore/rewind planners — pure, no I/O</td></tr><tr><td><code>sepia-proto</code></td><td><code>SessionEvent</code> enum and wire types</td></tr><tr><td><code>sepia-acp</code></td><td>Tolerant ACP client over ndjson stdio</td></tr><tr><td><code>sepia-driver</code></td><td>Driver manifest + the serve loop drivers run</td></tr><tr><td><code>sepia-host</code></td><td>Driver discovery, spawn, respawn</td></tr><tr><td><code>sepia-driver-{devin,cline,claude,cursor}</code></td><td>The per-agent adapter binaries</td></tr><tr><td><code>sepia-session</code></td><td>The local session plane — attach modes, lock probes, prompt/cancel/permission, restore/rewind</td></tr><tr><td><code>sepia-meta</code>, <code>sepia-convert</code></td><td>Overlay store; cross-store conversion/import</td></tr><tr><td><code>sepia-telemetry</code></td><td>Opt-in OTEL layer over <code>tracing</code></td></tr><tr><td><code>sepia-peregrin</code></td><td>The entity-plane adapter — sessions as <code>kind=&quot;sepia-session&quot;</code> entities (<code>/api/entities*</code> client + server side)</td></tr><tr><td><code>sepia-cli</code></td><td>The <code>sepia</code> binary — store/driver/config verbs + <code>serve</code></td></tr><tr><td><code>sepia-driver-pavo</code></td><td><code>tamias-driver-sepia</code> — pavo&#39;s read-only view driver, proxying <code>sepia serve</code></td></tr><tr><td><code>sepia-testkit</code></td><td>Conformance suites, golden fixtures, mock ACP agent</td></tr></tbody></table><h2 id="the-service-wire" tabindex="-1">The service wire <a class="header-anchor" href="#the-service-wire" aria-label="Permalink to &quot;The service wire&quot;">​</a></h2><p><code>sepia serve</code> is the embedding contract. <code>manifest</code> negotiates protocol versions; <code>sessions.*</code>, <code>agents.*</code>, <code>projects.*</code>, <code>config.*</code>, and the two <code>*.subscribe</code> feeds cover the plane&#39;s surface; <code>session.event</code> and <code>node.event</code> notifications stream live events. The full method table lives in <a href="./../reference/serve-wire.html">serve-wire</a> and <code>crates/sepia-cli/src/serve.rs</code>.</p>`,13)])])}const m=s(o,[["render",i]]);export{v as __pageData,m as default};
